import { ENV } from '@/utils/env/environmentFix';

// Simple Supabase configuration validation
export const verifySupabaseConfig = () => {
  try {
    console.log('🔧 Supabase config verification: Starting...');
    
    const url = ENV.SUPABASE_URL;
    const key = ENV.SUPABASE_ANON_KEY;
    
    if (!url || !key) {
      console.warn('⚠️ Supabase config incomplete - using fallback');
      return false;
    }
    
    console.log('✅ Supabase config verification: Valid');
    return true;
    
  } catch (error) {
    console.warn('⚠️ Supabase config verification failed:', error);
    return false;
  }
};

console.log('🔧 SupabasePatch loaded successfully');
